// @generated by:gauntlet run:laravel-session-cookie
mod common;

use anatoly::{scan::scan_configured, scan_options::ScanOptions};
use common::{Server, limits, response};
use serde_json::{Value, json};

fn inspect(name: &str, no_cookie_hints: bool, no_hypotheses: bool) -> Value {
    let headers = format!(
        "Set-Cookie: {name}=private-cookie-value-should-not-appear; Path=/; HttpOnly; SameSite=Lax\r\n"
    );
    let server = Server::new(move |_| response("200 OK", &headers, "application"));
    let mut options = ScanOptions {
        samples: 1,
        discover: false,
        no_cookie_hints,
        no_hypotheses,
        ..ScanOptions::default()
    };
    options.network.no_proxy = true;
    let report =
        serde_json::to_value(scan_configured(&server.url, limits(), &options).unwrap()).unwrap();
    assert_eq!(server.paths.lock().unwrap().len(), 1);
    assert!(
        !report
            .to_string()
            .contains("private-cookie-value-should-not-appear")
    );
    report
}

fn laravel(report: &Value) -> Option<&Value> {
    report["technologies"]
        .as_array()
        .unwrap()
        .iter()
        .find(|technology| technology["name"] == "Laravel")
}

fn assert_unknown_version(report: &Value) {
    assert!(report["version"].is_null());
    assert_eq!(report["version_status"], "unknown");
    assert!(report["version_candidates"].as_array().unwrap().is_empty());
}

#[test]
fn canonical_hyphenated_and_underscored_laravel_cookies_identify_the_framework_without_versions() {
    for name in ["laravel-session", "laravel_session"] {
        let report = inspect(name, false, false);
        let framework =
            laravel(&report).expect("canonical Laravel session cookie must be recognized");
        assert_eq!(framework["versions"], json!([]));
        assert_eq!(framework["runtime_hint"], "PHP");
        assert!(
            framework["observations"]
                .as_array()
                .unwrap()
                .iter()
                .any(|observation| observation["method"] == "cookie_name")
        );
        assert_eq!(report["runtime"]["status"], "inferred");
        assert_unknown_version(&report);
    }
}

#[test]
fn similarly_named_cookies_do_not_identify_laravel() {
    for name in ["laravel-sessionish", "my-laravel-session"] {
        let report = inspect(name, false, false);
        assert!(laravel(&report).is_none());
        assert_eq!(report["runtime"]["status"], "unknown");
        assert_unknown_version(&report);
    }
}

#[test]
fn disabling_cookie_hints_suppresses_laravel_recognition_from_both_canonical_names() {
    for name in ["laravel-session", "laravel_session"] {
        let report = inspect(name, true, false);
        assert!(laravel(&report).is_none());
        assert_eq!(report["runtime"]["status"], "unknown");
        assert_unknown_version(&report);
    }
}

#[test]
fn disabling_hypotheses_retains_cookie_technology_without_inferring_a_php_runtime() {
    for name in ["laravel-session", "laravel_session"] {
        let report = inspect(name, false, true);
        let framework =
            laravel(&report).expect("technology declarations survive hypothesis suppression");
        assert_eq!(framework["versions"], json!([]));
        assert_eq!(framework["runtime_hint"], "PHP");
        assert_eq!(report["runtime"]["status"], "unknown");
        assert_unknown_version(&report);
    }
}
